// How free-for-all and team fights play (docs/GAME_MODES.md, "Spawns, protection and awards"): spawn protection by
// mode, how a spawn point is chosen, what a heavy hit is, the awards' and callouts' thresholds.
//
//   node tools/content/match-play.mjs           check the content and write the generated file
//   node tools/content/match-play.mjs --check   check the content, and that the generated file is up to date
//
// Reads content/match-play.json. Checks the schema (unknown fields are errors) and the ranges (protection 0-5 s, a
// mode id the game knows), then writes packages/shared/src/content/matchPlay.generated.ts. Behaviour stays in code
// (sim/spawns.ts, sim/awards.ts, sim/match.ts).

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { check, shape, tsInline } from './weapons.mjs';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const FILE = 'content/match-play.json';
const GENERATED = 'packages/shared/src/content/matchPlay.generated.ts';

const { num, int, str, map, obj } = shape;

/** The game's modes (sim/rules.ts GameMode). */
function modeIds(root) {
  const src = readFileSync(join(root, 'packages/shared/src/sim/rules.ts'), 'utf8');
  const m = src.match(/export type GameMode =([^;]*);/);
  return new Set(m ? [...m[1].matchAll(/'(core\.[a-z]+)'/g)].map((x) => x[1]) : []);
}

export function build(root = ROOT) {
  const problems = [];
  const d = JSON.parse(readFileSync(join(root, FILE), 'utf8'));
  const choice = obj({ enemyRange: num, sightRange: num, sightCandidates: int, sightEnemies: int, seenPenalty: num, deathRadius: num, deathSeconds: num, deathPenalty: num, mateRange: num, mateBonus: num, mateMax: int, sideWeight: num, sideMax: num, safeFew: int, margin: num });
  const top = obj({ $comment: str, spawnProtection: map(num), spawnChoice: choice, heavyHit: num, awards: obj({ accuracyMinShots: int, streakMin: int, nemesisMin: int, revengeMin: int }), callouts: obj({ nemesis: int }) });
  problems.push(...check(d, top, FILE));
  if (problems.length) return { problems, out: null };
  const modes = modeIds(root);
  for (const [m, s] of Object.entries(d.spawnProtection)) {
    if (!modes.has(m)) problems.push(`${FILE}: spawnProtection.${m} isn't a mode (${[...modes].join(', ')})`);
    if (!(s >= 0 && s <= 5)) problems.push(`${FILE}: spawnProtection.${m} must be 0-5 seconds`);
  }
  const c = d.spawnChoice;
  for (const k of ['enemyRange', 'sightRange', 'deathRadius', 'mateRange']) if (!(c[k] > 0 && c[k] <= 200)) problems.push(`${FILE}: spawnChoice.${k} must be over 0 and at most 200 m`);
  for (const k of ['seenPenalty', 'deathPenalty', 'mateBonus', 'margin']) if (!(c[k] >= 0 && c[k] <= 200)) problems.push(`${FILE}: spawnChoice.${k} must be 0-200`);
  if (!(c.deathSeconds > 0 && c.deathSeconds <= 60)) problems.push(`${FILE}: spawnChoice.deathSeconds must be over 0 and at most 60`);
  if (!(c.sideWeight >= 0 && c.sideWeight <= 2)) problems.push(`${FILE}: spawnChoice.sideWeight must be 0-2`);
  if (!(c.sideMax >= 0 && c.sideMax <= 50)) problems.push(`${FILE}: spawnChoice.sideMax must be 0-50`);
  if (!(c.safeFew >= 1 && c.safeFew <= 8)) problems.push(`${FILE}: spawnChoice.safeFew must be 1-8`);
  if (!(c.sightCandidates >= 1 && c.sightCandidates <= 16) || !(c.sightEnemies >= 1 && c.sightEnemies <= 8)) problems.push(`${FILE}: spawnChoice.sightCandidates must be 1-16 and sightEnemies 1-8 (each pair is a ray)`);
  if (!(c.mateMax >= 0 && c.mateMax <= 8)) problems.push(`${FILE}: spawnChoice.mateMax must be 0-8`);
  if (!(d.heavyHit >= 10 && d.heavyHit <= 200)) problems.push(`${FILE}: heavyHit must be 10-200 damage`);
  for (const [k, v] of Object.entries(d.awards)) if (!(v >= 1 && v <= 200)) problems.push(`${FILE}: awards.${k} must be 1-200`);
  if (!(d.callouts.nemesis >= 2 && d.callouts.nemesis <= 10)) problems.push(`${FILE}: callouts.nemesis must be 2-10`);
  const { $comment: _c, ...out } = d;
  return { problems, out };
}

export function render(out) {
  const L = [];
  L.push('// Generated by tools/content/match-play.mjs from content/match-play.json. Do not edit by hand: edit the JSON and run');
  L.push('// `node tools/content/match-play.mjs`.');
  L.push('');
  L.push('/** How free-for-all and team fights play (content/match-play.json; what each field means: its $comment). */');
  L.push('export const MATCH_PLAY = {');
  for (const [k, v] of Object.entries(out)) L.push(`  ${k}: ${tsInline(v)},`);
  L.push('} as const;');
  return `${L.join('\n')}\n`;
}

function main() {
  const checkOnly = process.argv.includes('--check');
  const { problems, out } = build();
  if (problems.length) {
    console.error(`match-play: ${problems.length} problem(s)\n  ${problems.join('\n  ')}`);
    process.exit(1);
  }
  const text = render(out);
  const stale = !existsSync(join(ROOT, GENERATED)) || readFileSync(join(ROOT, GENERATED), 'utf8') !== text;
  if (checkOnly) {
    if (stale) {
      console.error(`match-play: out of date: ${GENERATED} (run node tools/content/match-play.mjs)`);
      process.exit(1);
    }
  } else if (stale) writeFileSync(join(ROOT, GENERATED), text);
  console.log(`match-play OK: protection in ${Object.keys(out.spawnProtection).length} modes${checkOnly ? '' : stale ? `; wrote ${GENERATED}` : '; up to date'}`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
